const locale=language=>language==='nl'?'nl-NL':'en-GB';
const dictionary=language=>copy[language==='nl'?'nl':'en'];
const number=(value,language,digits=0)=>new Intl.NumberFormat(locale(language),{maximumFractionDigits:digits,minimumFractionDigits:digits}).format(Number.isFinite(Number(value))?Number(value):0);
const date=(value,language)=>{if(value===undefined||value===null||value==='')return dictionary(language).unknownDate;const d=new Date(value);return Number.isFinite(d.getTime())?new Intl.DateTimeFormat(locale(language),{dateStyle:'medium',timeStyle:'short'}).format(d):dictionary(language).unknownDate;};
const icons={cloud:'<path d="M6 17a4 4 0 0 1-.6-8 6 6 0 0 1 11.4-1A4.5 4.5 0 1 1 18 17Z"/><path d="m9 13 2 2 4-4"/>',passport:'<rect x="4" y="2" width="16" height="20" rx="3"/><circle cx="12" cy="9" r="3"/><path d="M8 16h8m-6 3h4M2 6h2m-2 4h2m-2 4h2m-2 4h2"/>',key:'<circle cx="8" cy="8" r="5"/><path d="m12 12 9 9m-5-5 3-3m-6 0 3-3"/>',trophy:'<path d="M7 3h10v5a5 5 0 0 1-10 0Zm5 10v5m-5 3h10m-7-3h4v3M7 5H3v2a4 4 0 0 0 4 4m10-6h4v2a4 4 0 0 1-4 4"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5M6 6a8 8 0 0 1 14 6M4 12a8 8 0 0 0 14 6"/>',fish:'<path d="M3 12c5-8 10-8 15-2l4-4v12l-4-4c-5 6-10 6-15-2Z"/><circle cx="7" cy="11" r=".7"/><path d="m11 7 2-3 2 4m-4 9 2 3 2-4"/>'};
const icon=name=>`<svg class="account-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.cloud}</svg>`;
const errKeys={INVALID_USERNAME:'invalidUsername',INVALID_PASSWORD:'invalidPassword',NOT_AUTHENTICATED:'sessionExpired',ACCOUNT_CHANGED:'accountChanged',REVISION_CONFLICT:'staleConflict',UPLOAD_ID_REUSED:'staleConflict',SAVE_TOO_LARGE:'saveTooLarge',NEWER_SAVE:'newerSave',INVALID_UPLOAD:'saveRejected',BUSY:'serverError',INVALID_CREDENTIALS:'credentialsError',UNAUTHORIZED:'sessionExpired',SESSION_EXPIRED:'sessionExpired',USERNAME_TAKEN:'usernameTaken',USERNAME_EXISTS:'usernameTaken',INVALID_RECOVERY:'recoveryError',INVALID_RECOVERY_CODE:'recoveryError',RATE_LIMITED:'rateLimited',TOO_MANY_REQUESTS:'rateLimited',NETWORK_ERROR:'networkError',OFFLINE:'networkError',SERVER_ERROR:'serverError',SERVICE_UNAVAILABLE:'serverError',UNSUPPORTED:'unsupported',LOCAL_BLOCKED:'localBlocked',SAVE_REJECTED:'saveRejected',INVALID_SAVE:'saveRejected',CONFLICT:'staleConflict',BACKUP_FAILED:'backupError'};
const errorText=(error,t)=>t[errKeys[String(error?.code||error||'').toUpperCase()]]||t.genericError;
const statusOf=model=>Object.hasOwn(copy.en,model?.status)&&['guest','pending','connecting','synced','saving','offline','conflict','choice','error','blocked'].includes(model.status)?model.status:model?.user?'synced':'guest';
const storageBlocked=model=>Boolean(model?.localBlocked||model?.status==='blocked');
const disabled=model=>Boolean(model?.busy||['saving','connecting'].includes(model?.status));
const formFeedback=t=>`<p class="account-form-feedback" role="alert" hidden></p><span class="account-form-working" role="status" hidden>${t.busy}</span>`;
function statusPanel(model,language){
 const t=dictionary(language),status=statusOf(model);
 return `<div class="account-status" data-sync-state="${status}" role="status" aria-live="polite"><span class="account-status-light" aria-hidden="true"></span><div><strong>${t[status]}</strong><p>${t[status+'Note']}</p>${model.lastSyncedAt?`<small>${t.lastSync} · ${esc(date(model.lastSyncedAt,language))}</small>`:''}</div>${icon('cloud')}</div>`;
}
function summaryCard(summary,title,language,{cloud=false}={}){
 const t=dictionary(language),s=summary||{};
 return `<article class="account-save-card ${cloud?'account-save-cloud':'account-save-local'}"><span class="account-save-source">${icon(cloud?'cloud':'passport')}${title}</span>${summary?`<div class="account-save-level"><strong>${number(s.level,language)}</strong><span>${t.level}</span></div><dl class="account-save-stats"><div><dt>${t.xp}</dt><dd>${number(s.xp,language)}</dd></div><div><dt>${t.catches}</dt><dd>${number(s.catches,language)}</dd></div><div><dt>${t.bestWeight}</dt><dd>${number(s.bestWeight,language,2)} <small>kg</small></dd></div></dl><p class="account-save-date">${t.updated}<time>${esc(date(s.updatedAt,language))}</time></p>`:`<p class="account-save-missing">${cloud?t.noCloud:t.noSummary}</p>`}</article>`;
}
function conflictPanel(model,language){
 const t=dictionary(language),conflict=model.conflict||{},busy=disabled(model),local=conflict.local||model.local,cloud=conflict.cloud??model.cloud;
 return `<section class="account-conflict panel" aria-labelledby="account-compare-heading"><div class="account-section-heading"><span class="eyebrow">${t[statusOf(model)==='choice'?'choice':'conflict']}</span><h2 id="account-compare-heading">${t.compareTitle}</h2><p>${t.compareIntro}</p></div><div class="account-save-options"><div>${summaryCard(local,t.localTitle,language)}<button type="button" class="primary account-choice-button" data-account-action="choose-local" ${busy||storageBlocked(model)?'disabled':''}>${t.localChoice}${icon('arrow')}</button><p class="account-choice-hint">${t.localChoiceHint}</p></div><div>${summaryCard(cloud,t.cloudTitle,language,{cloud:true})}<button type="button" class="secondary account-choice-button" data-account-action="choose-cloud" ${busy||!cloud?'disabled':''}>${t.cloudChoice}${icon('download')}</button><p class="account-choice-hint">${t.cloudChoiceHint}</p></div></div><p class="account-small-print">${t.backupNote}</p>${formFeedback(t)}</section>`;
}
function recoveryPanel(model,language){
 const t=dictionary(language),busy=disabled(model);
 return `<section class="account-recovery panel" aria-labelledby="account-code-title"><div class="account-section-heading"><span class="account-section-icon">${icon('key')}</span><div><span class="eyebrow">${t.recoveryCode}</span><h2 id="account-code-title">${t.recoveryTitle}</h2><p>${t.recoveryIntro}</p></div></div><label class="account-recovery-value"><span class="sr-only">${t.recoveryCode}</span><textarea readonly rows="2" spellcheck="false" autocomplete="off" data-user-text aria-label="${t.recoveryCode}">${esc(model.recoveryCode)}</textarea></label><p class="account-small-print">${t.recoveryWarning}</p><div class="account-action-row"><button class="primary" type="button" data-account-action="download-recovery" ${busy?'disabled':''}>${icon('download')}${t.downloadCode}</button><button class="button" type="button" data-account-action="acknowledge-recovery" ${busy?'disabled':''}>${t.savedCode}</button></div>${formFeedback(t)}</section>`;
}
function guestForms(model,language){
 const t=dictionary(language),busy=disabled(model),attrs=busy?'disabled':'';
 return `<div class="account-auth-grid"><section class="panel account-auth-card"><div class="account-section-heading"><span class="eyebrow">${t.login}</span><h2>${t.loginTitle}</h2></div><form data-account-form="login"><fieldset ${attrs}><legend class="sr-only">${t.login}</legend><label class="field"><span>${t.username}</span><input name="username" autocomplete="username" autocapitalize="none" spellcheck="false" minlength="3" maxlength="24" pattern="[A-Za-z0-9_-]{3,24}" required></label><label class="field"><span>${t.password}</span><input type="password" name="password" autocomplete="current-password" minlength="12" maxlength="128" required></label><button class="primary" type="submit">${t.loginAction}${icon('arrow')}</button></fieldset>${formFeedback(t)}</form><details class="account-recover-form"><summary>${t.recoverOpen}</summary><h3>${t.recoverTitle}</h3><p>${t.recoverIntro}</p><form data-account-form="recover"><fieldset ${attrs}><legend class="sr-only">${t.recoverTitle}</legend><label class="field"><span>${t.username}</span><input name="username" autocomplete="username" autocapitalize="none" spellcheck="false" minlength="3" maxlength="24" pattern="[A-Za-z0-9_-]{3,24}" required></label><label class="field"><span>${t.recoveryInput}</span><input name="recoveryCode" autocomplete="off" autocapitalize="none" spellcheck="false" maxlength="200" required></label><label class="field"><span>${t.newPassword}</span><input name="newPassword" type="password" autocomplete="new-password" minlength="12" maxlength="128" required aria-describedby="account-reset-password-hint"></label><p class="account-field-hint" id="account-reset-password-hint">${t.passwordHint}</p><label class="field"><span>${t.repeatPassword}</span><input name="repeatPassword" type="password" autocomplete="new-password" minlength="12" maxlength="128" required></label><button type="submit" class="secondary">${t.recoverAction}</button></fieldset>${formFeedback(t)}</form></details></section><section class="panel account-auth-card account-register-card"><div class="account-section-heading"><span class="eyebrow">${t.register}</span><h2>${t.registerTitle}</h2></div><form data-account-form="register"><fieldset ${attrs}><legend class="sr-only">${t.register}</legend><label class="field"><span>${t.username}</span><input name="username" autocomplete="username" autocapitalize="none" spellcheck="false" minlength="3" maxlength="24" pattern="[A-Za-z0-9_-]{3,24}" required aria-describedby="account-username-hint"></label><p class="account-field-hint" id="account-username-hint">${t.usernameHint}</p><label class="field"><span>${t.password}</span><input type="password" name="password" autocomplete="new-password" minlength="12" maxlength="128" required aria-describedby="account-password-hint"></label><p class="account-field-hint" id="account-password-hint">${t.passwordHint}</p><label class="field"><span>${t.repeatPassword}</span><input type="password" name="repeatPassword" autocomplete="new-password" minlength="12" maxlength="128" required></label><button class="primary" type="submit">${t.registerAction}${icon('arrow')}</button></fieldset>${formFeedback(t)}</form><p class="account-small-print">${t.publicName}</p></section></div>`;
}
function signedInPanel(model,language){
 const t=dictionary(language),user=model.user,busy=disabled(model),initials=String(user.username||'?').slice(0,2).toUpperCase();
 return `<div class="account-member-grid"><section class="account-member-pass"><span class="account-pass-label">${t.passLabel}</span><div class="account-pass-identity"><span class="account-avatar" data-user-text>${esc(initials)}</span><div><h2 data-user-text>${esc(user.username)}</h2><p>${t.memberSince} ${esc(date(user.createdAt,language))}</p></div>${icon('passport')}</div><div class="account-pass-seal">${icon('fish')}<span>EUROPEAN WATERS<br>ENDLESS POSSIBILITIES</span></div></section><section class="panel account-sync-actions"><div class="account-section-heading"><h2>${t.syncTitle}</h2><p>${t.syncIntro}</p></div><div class="account-action-row"><button type="button" class="primary" data-account-action="sync" ${busy||model.conflict||storageBlocked(model)?'disabled':''}>${icon('cloud')}${t.syncNow}</button><button type="button" class="button" data-account-action="backup" ${busy?'disabled':''}>${icon('download')}${t.backup}</button>${model.hasRecoveryBackup||model.recoveryBackupAvailable?`<button type="button" class="button" data-account-action="recovery-backup" title="${t.restoreBackupNote}" ${busy?'disabled':''}>${icon('download')}${t.restoreBackup}</button>`:''}</div><div class="account-signout"><button type="button" class="text-button" data-account-action="logout" ${busy?'disabled':''}>${t.logout}</button><span>${t.logoutNote}</span></div>${formFeedback(t)}</section></div><section class="account-local-overview"><div class="account-section-heading"><span class="eyebrow">${t.yourProgress}</span></div>${summaryCard(model.local,t.localTitle,language)}</section>`;
}
function hostedOnly(model,language){const t=dictionary(language);return `<section class="panel account-hosted-only"><span class="account-heading-emblem" aria-hidden="true">${icon('cloud')}</span><div class="account-section-heading"><h2>${t.hostedTitle}</h2><p>${t.hostedIntro}</p></div><div class="account-action-row"><a class="primary" href="https://europa-angler.daanpaalvastjunkmail.workers.dev/" target="_blank" rel="noopener noreferrer">${t.openHosted}${icon('arrow')}</a><button class="button" type="button" data-account-action="backup">${icon('download')}${t.backup}</button></div>${formFeedback(t)}</section>`;}
export function renderAccount(model={},language='en'){
 const t=dictionary(language),hasConflict=Boolean(model.conflict||['choice','conflict'].includes(model.status));
 return `<div class="account-page" data-account-page data-account-language="${language==='nl'?'nl':'en'}" data-no-translate><header class="page-heading account-page-heading"><div><span class="eyebrow">${t.eyebrow}</span><h1>${t.title}</h1><p>${t.intro}</p></div><span class="account-heading-emblem" aria-hidden="true">${icon('passport')}</span></header>${statusPanel(model,language)}${model.error||model.errorCode?`<div class="account-error notice" role="alert">${errorText(model.errorCode||model.error,t)}</div>`:''}${storageBlocked(model)?`<div class="account-error notice" role="alert">${t.localBlocked}</div>`:''}${model.available===false?hostedOnly(model,language):`${model.recoveryCode?recoveryPanel(model,language):''}${hasConflict?conflictPanel(model,language):''}${model.user?signedInPanel(model,language):guestForms(model,language)}`}<p class="account-bottom-note">${icon('cloud')}${t.offlineAvailable}</p></div>`;
}
const metrics=['xp','catches','biggest'];
const score=(row,metric,language)=>metric==='biggest'?`${number(row?.bestWeight??row?.biggest??row?.value,language,2)} kg`:number(row?.[metric]??row?.value,language);
export function renderLeaderboard(model={},language='en'){
 const t=dictionary(language),board=model.leaderboard||{},metric=metrics.includes(board.metric)?board.metric:'xp',rows=Array.isArray(board.rows)?board.rows:[],current=String(model.user?.username||'').toLowerCase(),candidate=board.ownEntry||(typeof board.ownRank==='object'&&board.ownRank?board.ownRank:null),matches=row=>Boolean(current&&String(row?.username||'').toLowerCase()===current),own=matches(candidate)?candidate:rows.find(matches),rank=own?.rank,ranked=Number.isFinite(Number(rank))&&Number(rank)>0,busy=Boolean(board.loading);
 let body;
 if(busy)body=`<div class="account-board-state" role="status"><span class="account-loader" aria-hidden="true"></span><h2>${t.boardLoading}</h2></div>`;
 else if(board.error||board.errorCode)body=`<div class="account-board-state account-board-error" role="alert">${icon('cloud')}<h2>${t.boardError}</h2><p>${errorText(board.errorCode||board.error,t)}</p><button type="button" class="secondary" data-account-action="refresh-leaderboard">${icon('refresh')}${t.retry}</button>${formFeedback(t)}</div>`;
 else if(!rows.length)body=`<div class="account-board-state">${icon('fish')}<h2>${t.boardEmpty}</h2><p>${t.boardEmptyNote}</p><button type="button" class="secondary" data-page="account">${t.openAccount}${icon('arrow')}</button></div>`;
 else body=`<div class="account-leaderboard-scroll"><table class="account-leaderboard-table"><caption class="sr-only">${t[metric]} · ${t.top}</caption><thead><tr><th scope="col">${t.rank}</th><th scope="col">${t.angler}</th><th scope="col">${t[metric]}</th></tr></thead><tbody>${rows.map((row,index)=>{const self=matches(row),position=Number.isFinite(Number(row.rank))&&Number(row.rank)>0?Number(row.rank):index+1;return `<tr class="${self?'is-current-player':''}" ${self?'aria-current="true"':''}><td><span class="account-rank ${position<=3?'is-podium':''}">${number(position,language)}</span></td><th scope="row"><span class="account-player-name" data-user-text>${esc(row.username)}</span>${self?`<span class="account-you">${t.you}</span>`:''}${row.prestige?`<small class="account-prestige">${t.prestige} ${number(row.prestige,language)}</small>`:''}</th><td class="account-board-score">${score(row,metric,language)}</td></tr>`;}).join('')}</tbody></table></div>`;
 return `<div class="account-page account-board-page" data-account-page data-account-language="${language==='nl'?'nl':'en'}" data-no-translate><header class="page-heading account-page-heading"><div><span class="eyebrow">${t.leaderboardEyebrow}</span><h1>${t.leaderboardTitle}</h1><p>${t.leaderboardIntro}</p></div><span class="account-heading-emblem account-board-emblem" aria-hidden="true">${icon('trophy')}</span></header><section class="account-own-rank"><div><span class="eyebrow">${t.yourRank}</span><strong>${ranked?'#'+number(rank,language):t.notRanked}</strong><p>${model.user?ranked?`${esc(model.user.username)} · ${t[metric]}${own?' · '+score(own,metric,language):''}`:t.rankPending:t.rankGuest}</p></div>${model.user?`<button class="secondary" type="button" data-account-action="sync" ${disabled(model)||model.conflict||storageBlocked(model)?'disabled':''}>${icon('cloud')}${t.syncNow}</button>`:`<button class="secondary" type="button" data-page="account">${t.login}${icon('arrow')}</button>`}${formFeedback(t)}</section><section class="panel account-leaderboard"><div class="account-board-toolbar"><div class="account-board-tabs" role="group" aria-label="${t.chooseMetric}">${metrics.map(id=>`<button type="button" data-account-metric="${id}" aria-pressed="${id===metric}" ${busy?'disabled':''}>${t[id]}</button>`).join('')}</div><button class="button account-refresh" type="button" data-account-action="refresh-leaderboard" ${busy?'disabled':''}>${icon('refresh')}<span>${t.refresh}</span></button></div>${Number.isFinite(Number(board.total))&&board.total!==null?`<p class="account-board-total">${number(board.total,language)} ${t.players}</p>`:''}${body}<div class="account-board-footer">${metric==='xp'?`<p>${t.xpOrder}</p>`:''}<p>${t.boardFootnote}</p><p>${t.boardPrivacy}</p></div></section></div>`;
}

/**
 * Controller methods: register({username,password}), login({username,password}),
 * recover({username,recoveryCode,newPassword}), logout(), syncNow(),
 * resolveConflict('local'|'cloud'), downloadLocalBackup(), downloadRecoveryCode(),
 * acknowledgeRecoveryCode(), loadLeaderboard('xp'|'catches'|'biggest'),
 * refreshLeaderboard(). A method may return a promise; false aborts an operation.
 * Local backup is awaited before replacing the local save with the online save.
 */
export function bindAccountUI(root,controller){
 if(!root?.addEventListener)throw new TypeError('Account UI needs an event root');
 let pending=false,disposed=false;
 const contains=element=>element&&root.contains(element);
 const textFor=element=>dictionary(element?.closest('[data-account-language]')?.dataset.accountLanguage||'en');
 const scopeFor=element=>element?.closest('form,.account-conflict,.account-recovery,.account-sync-actions,.account-own-rank,.account-board-state,.account-hosted-only')||element?.closest('[data-account-page]');
 const feedback=(scope,message)=>{const node=scope?.querySelector('.account-form-feedback');if(node){node.textContent=message||'';node.hidden=!message;}};
 const call=async(method,...args)=>{if(typeof controller?.[method]!=='function')throw {code:'UNSUPPORTED'};return await controller[method](...args);};
 const run=async(element,operation)=>{
  if(pending||disposed)return;pending=true;const scope=scopeFor(element),t=textFor(element),wasDisabled=new Map();feedback(scope,'');
  for(const input of scope?.querySelectorAll('button,input,select,textarea,fieldset')||[]){wasDisabled.set(input,input.disabled);input.disabled=true;}
  scope?.setAttribute('aria-busy','true');const working=scope?.querySelector('.account-form-working');if(working)working.hidden=false;
  try{await operation();}catch(error){if(!disposed)feedback(scope,scope?.dataset.accountForm==='recover'&&error?.code==='INVALID_CREDENTIALS'?t.recoveryError:errorText(error,t));}
  finally{pending=false;if(working)working.hidden=true;scope?.removeAttribute('aria-busy');for(const [input,value]of wasDisabled)input.disabled=value;}
 };
 const onSubmit=event=>{
  const form=event.target?.closest?.('form[data-account-form]');if(!contains(form))return;event.preventDefault();if(pending||disposed)return;
  const t=textFor(form),get=name=>form.elements.namedItem(name)?.value||'';feedback(form,'');
  const repeat=form.elements.namedItem('repeatPassword');if(repeat)repeat.setCustomValidity('');
  if(typeof form.reportValidity==='function'&&!form.reportValidity()){feedback(form,t.invalidForm);return;}
  const kind=form.dataset.accountForm,username=get('username').trim(),password=get(kind==='recover'?'newPassword':'password');
  if(repeat&&repeat.value!==password){repeat.setCustomValidity(t.mismatch);feedback(form,t.mismatch);repeat.focus();return;}
  const payload=kind==='recover'?{username,recoveryCode:get('recoveryCode').trim(),newPassword:password}:{username,password};
  void run(form,async()=>{const result=await call(kind,payload);if(result!==false&&form.isConnected){form.querySelectorAll('input[type="password"],input[name="recoveryCode"]').forEach(input=>{input.value='';});}});
 };
 const onClick=event=>{
  const button=event.target?.closest?.('[data-account-action],[data-account-metric]');if(!contains(button)||button.disabled||pending||disposed)return;event.preventDefault();
  const action=button.dataset.accountAction,metric=button.dataset.accountMetric;
  if(metric){if(metrics.includes(metric))void run(button,()=>call('loadLeaderboard',metric));return;}
  const methods={sync:'syncNow',backup:'downloadLocalBackup',logout:'logout','download-recovery':'downloadRecoveryCode','acknowledge-recovery':'acknowledgeRecoveryCode','refresh-leaderboard':'refreshLeaderboard','recovery-backup':'downloadRecoveryBackup'};
  if(action==='choose-cloud')void run(button,async()=>{const saved=await call('downloadLocalBackup');if(saved===false)throw {code:'BACKUP_FAILED'};return call('resolveConflict','cloud');});
  else if(action==='choose-local')void run(button,()=>call('resolveConflict','local'));
  else if(methods[action])void run(button,()=>call(methods[action]));
 };
 const onInput=event=>{const form=event.target?.closest?.('form[data-account-form]');if(!contains(form))return;form.elements.namedItem('repeatPassword')?.setCustomValidity('');feedback(form,'');};
 root.addEventListener('submit',onSubmit);root.addEventListener('click',onClick);root.addEventListener('input',onInput);
 return ()=>{disposed=true;root.removeEventListener('submit',onSubmit);root.removeEventListener('click',onClick);root.removeEventListener('input',onInput);};
}
